`pragma protect end_protected
module SPI_Flash_Interface_Top (
  I_hclk,
  I_hresetn,
  I_haddr_reg,
  O_hrdata_reg,
  I_hreadyin_reg,
  O_hreadyout_reg,
  O_hresp_reg,
  I_hsel_reg,
  I_htrans_reg,
  I_hwdata_reg,
  I_hwrite_reg,
  I_spi_clock,
  I_spi_rstn,
  O_flash_ck,
  O_flash_cs_n,
  IO_flash_hold_n,
  IO_flash_wp_n,
  IO_flash_do,
  IO_flash_di
)
;
input I_hclk;
input I_hresetn;
input [31:0] I_haddr_reg;
output [31:0] O_hrdata_reg;
input I_hreadyin_reg;
output O_hreadyout_reg;
output [1:0] O_hresp_reg;
input I_hsel_reg;
input [1:0] I_htrans_reg;
input [31:0] I_hwdata_reg;
input I_hwrite_reg;
input I_spi_clock;
input I_spi_rstn;
output O_flash_ck;
output O_flash_cs_n;
inout IO_flash_hold_n;
inout IO_flash_wp_n;
inout IO_flash_do;
inout IO_flash_di;
wire IO_flash_do_in;
wire IO_flash_do_8;
wire I_spi_clock_d_1;
wire IO_flash_di_d;
wire spi_miso_oe;
wire VCC;
wire GND;
  OBUF IO_flash_hold_n_obuf (
    .O(IO_flash_hold_n),
    .I(VCC) 
);
  OBUF IO_flash_wp_n_obuf (
    .O(IO_flash_wp_n),
    .I(VCC) 
);
  IOBUF IO_flash_do_iobuf (
    .O(IO_flash_do_in),
    .IO(IO_flash_do),
    .I(VCC),
    .OEN(IO_flash_do_8) 
);
  OBUF IO_flash_di_obuf (
    .O(IO_flash_di),
    .I(IO_flash_di_d) 
);
  INV IO_flash_do_s5 (
    .O(IO_flash_do_8),
    .I(spi_miso_oe) 
);
  INV I_spi_clock_d_s (
    .O(I_spi_clock_d_1),
    .I(I_spi_clock) 
);
  \~spiflash.SPI_Flash_Interface_Top  spiflash_inst (
    .I_hclk(I_hclk),
    .I_hwrite_reg(I_hwrite_reg),
    .I_hsel_reg(I_hsel_reg),
    .I_hreadyin_reg(I_hreadyin_reg),
    .I_hresetn(I_hresetn),
    .I_spi_rstn(I_spi_rstn),
    .I_spi_clock(I_spi_clock),
    .IO_flash_do_in(IO_flash_do_in),
    .I_spi_clock_d_1(I_spi_clock_d_1),
    .I_haddr_reg(I_haddr_reg[6:2]),
    .I_htrans_reg(I_htrans_reg[1]),
    .I_hwdata_reg(I_hwdata_reg[31:0]),
    .O_hreadyout_reg(O_hreadyout_reg),
    .IO_flash_di_d(IO_flash_di_d),
    .spi_miso_oe(spi_miso_oe),
    .O_flash_cs_n(O_flash_cs_n),
    .O_flash_ck(O_flash_ck),
    .O_hrdata_reg(O_hrdata_reg[31:0])
);
  VCC VCC_cZ (
    .V(VCC)
);
  GND GND_cZ (
    .G(GND)
);
  GSR GSR (
    .GSRI(VCC) 
);
assign O_hresp_reg[0] = GND;
assign O_hresp_reg[1] = GND;
endmodule /* SPI_Flash_Interface_Top */
